{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 차 업무 적용형 최소 RAG 시제품 구축 로드맵",
  "summary": "사용자의 Python 경험과 2주(주 3시간)의 제한된 시간을 고려하여, 이론 중심이 아닌 '가상 규정 3건'을 데이터로 활용한 최소 RAG 시제품 구축에 집중합니다. 검색 성공, 근거 누락, 답변 불가(거절)의 3가지 시나리오를 명확히 구분하는 로직 구현을 목표로 하며, 검색된 무료 Microsoft Learn 자료를 활용하여 비용 부담 없이 학습을 진행합니다. 규정 관련 지원금은 미확정 상태이므로 현금 예산(20,000원) 내에서 무료 자원만 활용하도록 계획했습니다.",
  "project_goal": "가상 규정 3건을 데이터로 하여 질문 5건에 대해 근거를 표시하고, 근거가 없는 질문은 '답변 불가'로 구분하는 최소 RAG 시제품 구현",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 이해 및 데이터 준비",
      "duration": "1주 (3시간)",
      "focus": "RAG의 기본 흐름(Chunking, Embedding, Retrieval, Generation) 이해 및 가상 규정 3건의 텍스트 데이터 전처리"
    },
    {
      "step": 2,
      "title": "최소 RAG 파이프라인 구현 및 시나리오 검증",
      "duration": "1주 (3시간)",
      "focus": "Python 기반 RAG 코드 작성, 검색 성공/근거 누락/답변 불가 3가지 케이스에 대한 로직 구현 및 테스트"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기반 구축 및 데이터 준비",
      "duration": "1주",
      "focus_goal": "RAG 개념 정립 및 가상 규정 데이터의 벡터화 준비",
      "key_actions": [
        "Microsoft Learn 'Microsoft Foundry를 사용하여 생성 AI 모델 성능 최적화' 모듈 중 RAG 관련 섹션 학습",
        "가상 규정 3건의 텍스트를 의미 단위로 분할(Chunking)하는 Python 스크립트 작성",
        "Embedding 모델 선택 및 텍스트 벡터화 과정 이해"
      ],
      "deliverables": [
        "가상 규정 3건의 Chunking된 데이터셋(JSON/CSV)",
        "RAG 파이프라인 설계 도식(텍스트)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "시제품 구현 및 시나리오 검증",
      "duration": "1주",
      "focus_goal": "검색 및 생성 로직 구현, 3가지 응답 시나리오(성공/누락/불가) 구분 로직 완성",
      "key_actions": [
        "Microsoft Learn '추적을 사용하여 생성형 AI 앱 분석 및 디버그' 모듈 참고하여 검색 결과 추적 로직 구현",
        "질문 5건에 대한 검색 점수(Similarity Score) 임계값 설정을 통한 '근거 있음/없음' 판별 로직 작성",
        "근거 없는 질문에 대한 '답변 불가' 메시지 반환 및 근거 있는 질문에 대한 출처 표시 로직 구현",
        "테스트 질문 5건 실행 및 결과 검증"
      ],
      "deliverables": [
        "최소 RAG 시제품 Python 코드",
        "질문 5건에 대한 실행 결과 로그(검색 성공, 근거 누락, 답변 불가 구분 포함)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": [],
  "clarification_questions": []
}
